// Let it throw. Catching here would hide the failure from the diagram
// and the process would carry on down the happy path with no order.
if (string.IsNullOrEmpty(Input.orderId))
    throw new Exception("orderId is required");

Logger.LogInformation($"order {Input.orderId} accepted");
return new OrderRequest() { orderId = Input.orderId };

